SELECT COALESCE(SUM(sr.amount), 0) FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'EXPENSE' AND COALESCE(sr.changed_category, sr.category) IN
#{category}

SELECT COALESCE(sr.changed_category, sr.category) AS categoryCode, COALESCE(SUM(sr.amount), 0) AS expenseAmount FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'EXPENSE' AND COALESCE(sr.changed_category, sr.category) IN
#{category}
GROUP BY COALESCE(sr.changed_category, sr.category)

SELECT MIN(sr.record_date) FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'EXPENSE' AND COALESCE(sr.changed_category, sr.category) IN
#{category}

SELECT DATE_FORMAT(sr.record_date, '%Y-%m') AS yearMonth, COALESCE(SUM(sr.amount), 0) AS expenseAmount FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.type = 'EXPENSE' AND COALESCE(sr.changed_category, sr.category) IN
#{category}
AND sr.record_date BETWEEN #{startAt} AND #{endAt} GROUP BY DATE_FORMAT(sr.record_date, '%Y-%m') ORDER BY DATE_FORMAT(sr.record_date, '%Y-%m') ASC
